import { useCallback, useState } from "react";
import { Calendar, Chip, Inline, Tabs, Text } from "@kit/index.js";
import { daysBetween, today, useTrack, useTranslation } from "travel-platform";
import styles from "./DatePicker.module.css";

const FLEX_OPTIONS = [0, 1, 2, 3, 7];

export default function DatePicker({ checkin, checkout, onChange, onDone }) {
    const t = useTranslation();
    const track = useTrack();
    const [month, setMonth] = useState((checkin ?? today()).slice(0, 7));
    const [tab, setTab] = useState("calendar");
    const [flex, setFlex] = useState(0);
    const select = useCallback((day) => {
        if (!checkin || checkout || day <= checkin) {
            onChange({ checkin: day, checkout: null });
            return;
        }
        onChange({ checkout: day });
        track("datepicker.select", { nights: daysBetween(checkin, day) });
        onDone();
    }, [checkin, checkout, onChange, onDone, track]);
    const nights = checkin && checkout ? daysBetween(checkin, checkout) : 0;
    return (
        <div className={styles.picker}>
            <Tabs items={[{ id: "calendar", label: t("sb.calendar"), href: "#calendar" }, { id: "flexible", label: t("sb.flexible"), href: "#flexible" }]} selected={tab} variant="underline" label={t("sb.dates_title")} onSelect={setTab} />
            <Calendar month={month} today={today()} checkin={checkin} checkout={checkout} onSelect={select} onMonthChange={setMonth} labels={{ previous: t("sb.previous_month"), next: t("sb.next_month") }} testId="calendar" />
            <Inline gap={2} className={styles.footer} justifyContent="between">
                <Inline gap={2} wrap>
                    {FLEX_OPTIONS.map((days) => (
                        <button key={days} type="button" className={styles.flex} aria-pressed={flex === days} onClick={() => setFlex(days)}>
                            <Chip selected={flex === days}>{days === 0 ? t("sb.exact") : t(days === 1 ? "sb.plus_minus" : "sb.plus_minus_many", { count: days })}</Chip>
                        </button>
                    ))}
                </Inline>
                {nights ? <Text variant="strong_2">{t("sb.nights", { count: nights })}</Text> : null}
            </Inline>
        </div>
    );
}
